test_fine_resources.INSTALLATION.source:
schema: graph_cli.policy/1
id: installation
roles:
  importer: {description: "Importers: notes and topics"}
  tagger: {description: "Taggers: retag notes"}
  editor: {description: "Editors: write every graph"}
grants:
  - entrypoint: server
    principal: {role: importer}
    graphs: [example_graph]
    level: read
    writes:
      nas:Note:
        create: [title, body, kind]
        update: [body]
        link: [nas:about]
        transition: true
      nas:Topic: {create: true}
  - entrypoint: server
    principal: {role: tagger}
    graphs: [example_graph]
    level: read
    writes:
      nas:Note: {update: [kind]}
  - {entrypoint: server, principal: {role: editor}, graphs: [example_graph], level: write}
scopes:
  example_project: {example_graph: write}
  another_project: {example_graph: read}
no_project: {"*": read}

test_markings.INSTALLATION.source:
schema: graph_cli.policy/1
id: installation
roles:
  hr: {description: "HR: personal data of people"}
  leads: {description: "Team leads: internal notes"}
  reporting: {description: "Reporting: people without personal data"}
  editor: {description: "Editors: update some people attributes"}
  wide: {description: "Wide editors: update every people attribute"}
grants:
  - {entrypoint: server, principal: {role: hr}, graphs: [example_graph], level: write,
     markings: [ex:personal]}
  - {entrypoint: server, principal: {role: leads}, graphs: [example_graph], level: read,
     markings: [ex:team_internal]}
  - {entrypoint: server, principal: {role: reporting}, graphs: "*", level: read}
  - entrypoint: server
    principal: {role: editor}
    graphs: [example_graph]
    level: read
    writes:
      ex:Person: {update: [name, team]}
  - entrypoint: server
    principal: {role: wide}
    graphs: [example_graph]
    level: read
    writes:
      ex:Person: {update: true}
scopes:
  frozen_project: {example_graph: none}
  ops: {example_graph: maintain}
no_project: {"*": write}
deny:
  - {id: no_explorers, agent_type: [explore], action: ["read.*", "write.*"], graph: "*"}

test_read_limits.INSTALLATION.source:
schema: graph_cli.policy/1
id: installation
roles:
  reporting: {description: "Reporting: notes and topics only"}
  auditor: {description: "Auditors: read everything"}
  curator: {description: "Curators: read and write books only"}
grants:
  - entrypoint: server
    principal: {role: reporting}
    graphs: [example_graph]
    level: read
    reads: [nas:Topic, nas:Note]
  - {entrypoint: server, principal: {role: auditor}, graphs: [example_graph], level: read}
  - entrypoint: server
    principal: {role: curator}
    graphs: [example_graph, other_graph]
    level: read
    reads: ["nas:*"]
    writes:
      nas:Book: {create: true}
scopes:
  frozen_project: {example_graph: none}
no_project: {"*": read}

test_roles.GRANT_HEAVY_INSTALLATION.source:
schema: graph_cli.policy/1
id: installation
roles:
  importer: {description: "Importers: findings in example_graph"}
  tagger: {description: "Taggers: read every graph"}
grants:
  - {principal: {name: tester}, graphs: "*", level: write}
  - {entrypoint: app, graphs: [example_graph, other_graph], level: read}
  - {entrypoint: server, principal: {project: example_project},
     graphs: [example_graph], level: write}
  - {entrypoint: server, principal: {role: importer}, graphs: [example_graph], level: write}
  - {entrypoint: server, principal: {role: tagger}, graphs: "*", level: read}
  - {entrypoint: server, principal: {role: tagger, project: example_project},
     graphs: [other_graph, third_graph], level: write}
  - {entrypoint: [server, app], principal: {id: "token:ci"}, graphs: [third_graph], level: read}
maintainers:
  - {name: boss}
scopes:
  example_project: {example_graph: write, other_graph: read, third_graph: maintain}
  another_project: {other_graph: write, "*": read}
no_project: {"*": read, third_graph: none}
deny:
  - {id: no_explore_writes, agent_type: [explore], action: ["write.*"]}
  - {id: no_server_retract, entrypoint: server, principal_name: ci,
     action: ["write.retract"], graph: [example_graph]}
  - {id: importer_no_retract, role: [importer], action: ["write.retract", "write.supersede"]}
  - {id: no_device_unlink, device_id: dev-1, action: ["write.unlink"], graph: "*"}
obligations:
  - {action: ["write.*"], max_batch: 100}
  - {action: ["write.retract"], require_reason: true}

