    graphs: [example_graph]
    level: read
    writes:
      nas:Note: {update: [kind], transition: [status]}
      nas:Missing: {create: true}
  - {entrypoint: server, principal: {role: maintainer}, graphs: [example_graph], level: write}
no_project: {"*": write}

